  Lemma hole_sel_here : forall w, world_ok w (pm_short sp0z) g -> hole_sel w h = true.
  Proof.
    intros [wu wb] [H1 H2]. unfold hole_sel. cbn [w_uw w_brk] in *. rewrite hole_short_pm in H1. rewrite H1, H2. reflexivity.
